    },
    "question": "What is the onset order of metric deviations across components?",
    "target_hypothesis_ids": [
      "H1-redis-cpu-saturation",
      "H2-adservice-service-error",
      "H3-frontend-service-error",
      "H4-recommendationservice-latency-degradation",
      "H5-paymentservice-latency-degradation"
    ],
    "tool_name": "compare_onset_order",
    "why_discriminative": "Onset order can triage early vs. late candidates; if some components onset significantly later, they are unlikely root causes."
  }
}

